def placed_script(run_id: str) -> dict:
    return PLACED_SCRIPTS[run_id]


def recorded_states(run_id: str, name: str) -> list:
    return [fields for state, fields in PLACED_SCRIPTS[run_id]["states"] if state == name]


class HomeFile:
    """The saved low scan pose of the day for the refusal methods that read it (the pan-bound one)."""

    def __init__(self, test: unittest.TestCase, pan_deg: float):
        directory = tempfile.TemporaryDirectory(prefix="kc-recorded-home-")
        test.addCleanup(directory.cleanup)
        path = Path(directory.name) / "scan-home.json"
        path.write_text(json.dumps({"measured_joints_deg": {"shoulder_pan": pan_deg}}))
        for target in (cycle, cycle.cli):
            patch = mock.patch.object(target, "HOME_FILE", path)
            patch.start()
            test.addCleanup(patch.stop)


def bare_cycle():
    """A Cycle with no robot, no camera and no events: enough for the refusal methods, which only compute and raise."""
    machine = cycle.Cycle.__new__(cycle.Cycle)
    machine.transitions, machine.abort = [], {"set": False}
    return machine


class TheGraspMissOf1919(unittest.TestCase):
    """Run m8c5f9e9 (item 1): the block lay nearer than the proven grasp radius; ALIGN measured it; the grasp target was
    clamped at 0 and every empty close retried 14 mm outward. The last two are pinned through the harness's restatements of
    the controller's inline lines (see the module header)."""

    inputs = GRASP_MISS_INPUTS

    def test_the_coarse_pregrasp_is_minus_44_5_clamped_to_0_at_contact_495_696_and_pan_minus_8_7(self):
        self.assertEqual([495.0, 696.0], self.inputs["search_contact_px"])
        self.assertAlmostEqual(-8.7, self.inputs["search_pan_deg"], delta=0.005)
        coarse = cycle.coarse_pregrasp_from_low_pose(self.inputs["search_contact_px"], self.inputs["search_pan_deg"])
        self.assertEqual({"pan_deg": -13.53, "forward_mm": 0.0, "cube_out_mm": -44.5}, coarse)

    def test_the_merged_near_block_refusal_now_refuses_it_before_motion_with_the_distance_to_move(self):
        coarse = cycle.coarse_pregrasp_from_low_pose(self.inputs["search_contact_px"], self.inputs["search_pan_deg"])
        with self.assertRaises(cycle.CycleFailed) as refused:
            bare_cycle()._refuse_pregrasp_inside_grasp_radius(coarse, None)
        self.assertIn("31.5 mm nearer", str(refused.exception))
        self.assertIn("move it at least 57.5 mm away", str(refused.exception))

    def test_its_pregrasp_pan_lay_4_48_deg_from_the_saved_pose_inside_the_return_bound(self):
        HomeFile(self, self.inputs["home_pan_deg"])
        coarse = cycle.coarse_pregrasp_from_low_pose(self.inputs["search_contact_px"], self.inputs["search_pan_deg"])
        self.assertAlmostEqual(4.475, abs(coarse["pan_deg"] - self.inputs["home_pan_deg"]), delta=0.001)
        bare_cycle()._refuse_pregrasp_beyond_pan_bounds(coarse["pan_deg"], self.inputs["search_pan_deg"], None)  # no refusal

    def test_each_align_attempt_is_reproduced_from_its_recorded_box_and_pitch(self):
        recorded = [(1.6, -15.3, True, "-2.6 mm out / +68.7 mm up vs the proven grasp, pitch 64.7"), (2.1, -15.6, True, "-7.4 mm out / +38.8 mm up vs the proven grasp, pitch 66.3")]
        self.assertEqual(len(recorded), len(self.inputs["align"]))
        for (lateral, radial, aligned, tool_line), view in zip(recorded, self.inputs["align"]):
            tool = cycle.tool_state(view["joints"])
            decision = cycle.alignment_from_bbox(view["bbox_xyxy"], tool["pitch_deg"])
            self.assertEqual(tool_line, cycle.fmt_tool(tool))
            self.assertEqual((lateral, radial, aligned), (round(decision["lateral_mm"], 1), round(decision["radial_mm"], 1), decision["aligned"]))

    def test_the_block_was_measured_17_9_then_23_0_mm_inside_the_proven_radius(self):
        first, last = (cycle.tool_state(view["joints"]) for view in self.inputs["align"])
        radial = [cycle.alignment_from_bbox(view["bbox_xyxy"], cycle.tool_state(view["joints"])["pitch_deg"])["radial_mm"] for view in self.inputs["align"]]
        self.assertAlmostEqual(-17.9, first["out_mm"] + radial[0], delta=0.06)
        self.assertAlmostEqual(-23.0, last["out_mm"] + radial[1], delta=0.06)

    def test_the_recorded_approach_formula_gives_minus_9_0_mm_and_the_recorded_target_fwd_0(self):
        view = self.inputs["align"][-1]
        tool = cycle.tool_state(view["joints"])
        radial = cycle.alignment_from_bbox(view["bbox_xyxy"], tool["pitch_deg"])["radial_mm"]
        target = replay.approach_target_mm(cycle, round(tool["out_mm"], 1), round(radial, 1))  # the plan's numbers: tool -7.4, radial -15.6
        self.assertAlmostEqual(-9.0, target["unclamped_mm"], places=6)
        self.assertEqual(0.0, target["target_mm"])
        with self.assertRaises(cycle.ScanRefused):  # the proven grasp pose refuses anything nearer than its own radius
            cycle.proven_grasp_pose(view["joints"], -0.009, 0.002)
        # the recorded APPROACH pose is the one the proven grasp pose names for that target, from the joints it left
        pose, _report = cycle.proven_grasp_pose(self.inputs["approach_from_joints"], target["target_mm"] / 1000.0, 0.002)
        self.assertEqual("grasp-pose-fwd+0-dz+2", self.inputs["approach_pose_id"])
        self.assertEqual(self.inputs["approach_pose_id"], pose.pose_id)

    def test_the_three_closes_read_empty_and_each_retry_went_14_mm_outward(self):
        self.assertEqual([67.288, 67.15, 67.357], [round(value, 3) for value in self.inputs["closes"]])
        self.assertEqual([False, False, False], [cycle.closed_on_something(value) for value in self.inputs["closes"]])
        retries = [round(replay.retry_forward_mm(cycle, cycle.tool_state(joints)["out_mm"]), 1) for joints in self.inputs["reopened_joints"][:2]]
        self.assertEqual([9.8, 18.5], self.inputs["retry_to_forward_mm"])  # the recorded GRASP_RETRY_ADVANCE to_forward_mm
        self.assertEqual(self.inputs["retry_to_forward_mm"], retries)  # both outward of the block at -23.0


class TheCloseClassesOfEveryRecordedClose(unittest.TestCase):
    def test_three_empties_and_two_holds(self):
        holds = [step["readback"] for run_id in replay.PLACED_RUNS for step in placed_script(run_id)["steps"] if step["kind"] == "gripper" and step["label"] == "latch"]
        self.assertEqual([67.909, 68.185], [round(value, 3) for value in holds])
        self.assertEqual([True, True], [cycle.closed_on_something(value) for value in holds])
        self.assertEqual([False] * 3, [cycle.closed_on_something(value) for value in GRASP_MISS_INPUTS["closes"]])
        # the gap the latch class lives in (plan ruling 2): the worst empty and the lowest hold
        self.assertLess(max(GRASP_MISS_INPUTS["closes"]), cycle.GRIPPER_LATCH + cycle.GRIPPER_EMPTY_LATCH_MARGIN)
        self.assertGreater(min(holds), cycle.GRIPPER_LATCH + cycle.GRIPPER_EMPTY_LATCH_MARGIN)


class ThePlacedRunsReplayedThroughTheController(unittest.TestCase):
    """Starts 1 and 2 through Cycle.run_cycle: the recorded views in, the controller's own decisions out."""

    def replayed(self, run_id: str):
        result = replay.replay(cycle, placed_script(run_id))
        return result

    def assert_replays(self, run_id: str):
        result = self.replayed(run_id)
        self.assertIsNone(result.error, f"{run_id}: the replay ended with {result.error!r}")
        self.assertEqual([], result.mismatches, f"{run_id}: the controller commanded something the record did not do")
        self.assertEqual([], result.left_over, f"{run_id}: recorded steps the controller never asked for")
        self.assertEqual([], replay.compare_states(placed_script(run_id)["states"], result.states, compare_retention=False))
        self.assertEqual({"object_secured": True, "placed": True, "clearance_target_met": True, "base_returned": True},
                         {k: result.summary[k] for k in ("object_secured", "placed", "clearance_target_met", "base_returned")})
        return result

    def test_start_1_every_stage_decision_and_every_command(self):
        self.assert_replays(replay.START_1)

    def test_start_2_every_stage_decision_and_every_command(self):
        self.assert_replays(replay.START_2)

    def test_the_plan_numbers_by_name(self):
        """The decisions the plan names (section 5, P0c deliverable 2), read from the replay rather than from the record."""
        one, two = self.replayed(replay.START_1), self.replayed(replay.START_2)
        pick = lambda result, name: [fields for state, fields in result.states if state == name]  # noqa: E731
        self.assertEqual({"pan_deg": -11.26, "forward_mm": 20.1, "cube_out_mm": 7.1}, pick(one, "PREGRASP")[0]["coarse"])
        self.assertEqual({"pan_deg": -30.0, "forward_mm": 47.1, "cube_out_mm": 34.1}, pick(two, "PREGRASP")[0]["coarse"])
        self.assertEqual([(7.1, 3.2, True), (7.2, 6.7, True)], [(f["lateral_mm"], f["radial_mm"], f["aligned"]) for f in pick(one, "ALIGN")])
        self.assertEqual([(13.7, 0.7, False), (4.6, 1.2, True), (5.0, -0.4, True)], [(f["lateral_mm"], f["radial_mm"], f["aligned"]) for f in pick(two, "ALIGN")])
        approach = lambda result: next(pose for label, pose, _ in result.commanded if label == "APPROACH proven grasp geometry")  # noqa: E731
        self.assertEqual(("grasp-pose-fwd+29-dz+2", "grasp-pose-fwd+54-dz+2"), (approach(one), approach(two)))  # 7.9 + 6.7 + 14 and 40.2 - 0.4 + 14
        self.assertEqual([108.0, 82.0], [pick(result, "PLACEMENT_PLAN")[0]["base_advance_mm"] for result in (one, two)])
        self.assertEqual([[26.6, 40.1, 39.7, -40.0, -40.3, -23.5], [23.5, 42.1, 14.9, -40.2, -40.7]], [[f["advance_mm"] for f in pick(result, "BASE_MEASURED")] for result in (one, two)])
        self.assertEqual([-5.0, -4.1], [f["lateral_mm"] for f in pick(two, "BASE_MEASURED")][-2:])  # the reverse laterals against the tilted axis (plan item 3)
        self.assertEqual([43.8, 43.1], [pick(result, "RELEASE_ADMISSION")[0]["worst_case_centre_margin_mm"] for result in (one, two)])
        self.assertEqual([47.5, 51.1], [pick(result, "PLACED")[0]["centre_to_edge_mm"] for result in (one, two)])
        self.assertEqual([(2.9, -2.2), (-0.1, -9.1)], [(pick(r, "BASE_RETURNED")[0]["remaining_along_axis_mm"], pick(r, "BASE_RETURNED")[0]["sideways_mm"]) for r in (one, two)])

    def test_the_first_measured_pulse_of_each_run_from_its_two_recorded_homographies(self):
        """base_displacement directly, on the frame the loop measured against (the stamped capture after the rise) and the
        re-observation after the first pulse: the same numbers the replay states, without the loop around them."""
        for run_id, expected in ((replay.START_1, (26.6, -0.8, 0.17)), (replay.START_2, (23.5, -1.5, 0.18))):
            script = placed_script(run_id)
            plan = recorded_states(run_id, "PLACEMENT_PLAN")[0]
            steps = script["steps"]
            rise = next(i for i, step in enumerate(steps) if step["kind"] == "arm_pose" and step["label"].startswith("HOLD_OBSERVE"))
            before, after = steps[rise + 1]["records"][-1]["pad_by_template"], steps[rise + 3]["records"][-1]["pad_by_template"]
            anchor = next(step for step in steps if step["kind"] == "observe")["records"][-1]["cube_by_template"]["cube_center_pad_m"]
            direction = cycle.reach_direction_pad(steps[0]["records"][-1]["pad_by_template"]["homography_image_to_pad"], steps[0]["records"][-1]["cube"]["contact_px"])
            self.assertEqual(plan["reach_direction_pad"], [round(v, 3) for v in direction])
            moved = cycle.base_displacement(anchor, direction, before["homography_pad_to_image"], after["homography_image_to_pad"])
            self.assertEqual(expected, (round(moved["advance_mm"], 1), round(moved["lateral_mm"], 1), round(moved["distortion_mm"], 2)))


class TheRefusalsOfStart3And2117(unittest.TestCase):
    """Items 4 and 5: refused before motion with no word. The numbers the refusal carries (placement_refusal_values) name
    both limits of start 3 and the along-axis limit alone of 21:17."""

    def test_start_3_fails_the_side_rule_and_the_along_axis_bound(self):
        self.assertIsNone(cycle.base_advance_needed_mm(START_3, AXIS_START_1))
        with self.assertRaises(cycle.CycleFailed):
            cycle.placement_plan(START_3, AXIS_START_1, 0.0, cycle.PLACE_SIDE_DRIFT_ALLOWANCE_MM)
        values = cycle.placement_refusal_values(START_3, AXIS_START_1, cycle.PLACE_SIDE_DRIFT_ALLOWANCE_MM)
        self.assertAlmostEqual(44.5, values["side_margin_mm"], delta=0.01)
        self.assertAlmostEqual(58.96, values["required_side_margin_mm"], delta=0.01)
        self.assertAlmostEqual(121.6, values["axis_advance_needed_unbounded_mm"], delta=0.05)
        self.assertGreater(values["axis_advance_needed_unbounded_mm"], cycle.BASE_MAX_TOTAL_ADVANCE_MM)

    def test_2117_is_131_6_mm_along_the_axis_11_6_past_the_budget_and_its_side_is_clear(self):
        self.assertIsNone(cycle.base_advance_needed_mm(LATE_2117, AXIS_START_1))
        with self.assertRaises(cycle.CycleFailed):
            cycle.placement_plan(LATE_2117, AXIS_START_1, 0.0, cycle.PLACE_SIDE_DRIFT_ALLOWANCE_MM)
        values = cycle.placement_refusal_values(LATE_2117, AXIS_START_1, cycle.PLACE_SIDE_DRIFT_ALLOWANCE_MM)
        self.assertAlmostEqual(131.6, values["axis_advance_needed_unbounded_mm"], delta=0.05)
        self.assertAlmostEqual(11.6, values["axis_advance_needed_unbounded_mm"] - cycle.BASE_MAX_TOTAL_ADVANCE_MM, delta=0.05)
        self.assertGreater(values["side_margin_mm"], values["required_side_margin_mm"])

    def test_starts_1_and_2_plan_108_and_82_from_their_rounded_record_as_well(self):
        for run_id, advance in ((replay.START_1, 108.0), (replay.START_2, 82.0)):
            plan = recorded_states(run_id, "PLACEMENT_PLAN")[0]
            self.assertEqual(advance, cycle.base_advance_needed_mm(plan["anchor_pad_m"], plan["reach_direction_pad"]))


class TheReplayBites(unittest.TestCase):
    """The comparison is live: a changed decision in the controller shows up as a difference, never as a quiet pass."""

    def test_a_changed_reach_lead_is_a_different_grasp_pose(self):
        with mock.patch.object(cycle, "APPROACH_REACH_LEAD_MM", cycle.APPROACH_REACH_LEAD_MM + 1.0):
            result = replay.replay(cycle, placed_script(replay.START_1))
        self.assertTrue(any("grasp-pose-fwd+30" in line for line in result.mismatches), result.mismatches)

    def test_a_changed_placement_buffer_is_a_different_plan(self):
        with mock.patch.object(cycle, "BASE_TARGET_BUFFER_MM", cycle.BASE_TARGET_BUFFER_MM + 5.0):
            result = replay.replay(cycle, placed_script(replay.START_1))
        self.assertTrue(any("PLACEMENT_PLAN.base_advance_mm" in line for line in replay.compare_states(placed_script(replay.START_1)["states"], result.states, False)))

    def test_a_changed_capture_window_is_a_different_alignment(self):
        with mock.patch.object(cycle, "CAPTURE_WINDOW_MM", (0.0, 7.0)):
            result = replay.replay(cycle, placed_script(replay.START_1))
        differences = replay.compare_states(placed_script(replay.START_1)["states"], result.states, False)
        self.assertTrue(any("ALIGN.aligned" in line for line in differences) or result.mismatches, differences)

    def test_only_the_named_mission_fields_are_left_out(self):
        recorded = [["TARGET_SELECTED", {"mode": "BASE_ADVANCE"}], ["PLACED", {"value": True, "target_id": "cube", "centre_to_edge_mm": 47.5}], ["PLACEMENT_PLAN", {"bound_mode": "BASE_ADVANCE", "mode": "BASE_ADVANCE"}]]
        replayed = [["PLACED", {"value": True, "centre_to_edge_mm": 47.5}], ["PLACEMENT_PLAN", {"mode": "BASE_ADVANCE"}]]
        self.assertEqual([], replay.compare_states(recorded, replayed, False))
        self.assertEqual(["0 PLACED.centre_to_edge_mm: recorded 47.5, replayed 47.4"], replay.compare_states(recorded, [["PLACED", {"value": True, "centre_to_edge_mm": 47.4}], replayed[1]], False))
        self.assertEqual(["1 OBJECT_SECURED.retention_score: recorded 0.915, replayed 1.0"],
                         replay.compare_states([["SEARCH", {}], ["OBJECT_SECURED", {"retention_score": 0.915}]], [["SEARCH", {}], ["OBJECT_SECURED", {"retention_score": 1.0}]], True))

    def test_the_stamped_capture_after_the_rise_is_folded_into_the_rise_view_and_nothing_else_moves(self):
        script = placed_script(replay.START_1)
        folded = replay.legacy_script(script)
        self.assertEqual(len(script["steps"]) - 1, len(folded["steps"]))
        rise = next(step for step in folded["steps"] if step["kind"] == "arm_pose" and step["label"].startswith("HOLD_OBSERVE"))
        self.assertEqual(2, len(rise["records"]))
        self.assertTrue(math.isfinite(rise["records"][-1]["pad_by_template"]["homography_image_to_pad"][0][0]))


if __name__ == "__main__":
    unittest.main()
